const sr = function (runs, balls) { return (runs / balls) * 100; };
const sr2 = (runs, balls) => (runs / balls) * 100;   // arrow function

Arrow functions with one expression return it automatically. Functions are **values**: you can store them, pass them to other functions and return them.

const team = [
  { name: 'Aman', innings: [45, 12, 78] },
  { name: 'Bela', innings: [60, 55, 9] },
  { name: 'Chirag', innings: [5, 101, 20] }
];
const avg = arr => arr.reduce((s, x) => s + x, 0) / arr.length;
const withAvg = team.map(p => ({ ...p, avg: avg(p.innings) }));
const top = withAvg.reduce((best, p) => (p.avg > best.avg ? p : best));
console.log(top.name, top.avg.toFixed(1));

Aman 45.0, Bela 41.3, Chirag 42.0 → top is Aman. The ... **spread** copies an object's properties into a new object.

