async function loadUsers() {
  try {
    const res = await fetch('https://example.com/api/users');
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const users = await res.json();
    console.log(users.length, 'users');
  } catch (err) {
    console.error('Could not load:', err.message);
  }
}
loadUsers();

- **await** pauses *this function* (not the whole page) until the promise settles.
- fetch only rejects on network failure; a 404 or 500 still resolves — so check **res.ok**.

console.log('A');
setTimeout(() => console.log('B'), 0);
Promise.resolve().then(() => console.log('C'));
console.log('D');

Output: **A, D, C, B**. Synchronous code runs first; then promise callbacks (microtasks); then timer callbacks (tasks). This is a favourite interview question.

A **class** describes a kind of thing: what data it holds (**attributes**) and what it can do (**methods**). An **object** (instance) is one actual thing made from that blueprint.

class Account:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self._balance = balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError('Deposit must be positive')
        self._balance += amount

    def withdraw(self, amount):
        if amount > self._balance:
            raise ValueError('Insufficient funds')
        self._balance -= amount

    @property
    def balance(self):
        return self._balance

meena = Account('Meena', 500)
meena.deposit(200)
print(meena.balance)   # 700

class Account {
  #balance = 0;              // truly private field
  constructor(owner, balance = 0) { this.owner = owner; this.#balance = balance; }
  deposit(a) { if (a <= 0) throw new Error('Positive only'); this.#balance += a; }
  get balance() { return this.#balance; }
}
const a = new Account('Meena', 500);
a.deposit(200);
console.log(a.balance); // 700

class Vehicle:
    def __init__(self, reg, max_kg):
        self.reg, self.max_kg = reg, max_kg
    def cost(self, km):
        raise NotImplementedError

class Bike(Vehicle):
    def cost(self, km):
        return 4 * km

class Truck(Vehicle):
    def cost(self, km):
        return 25 * km + 500   # loading fee

A Bike **is a** Vehicle: it inherits __init__ and **overrides** cost(). super().__init__(...) calls the parent's version when you extend it.

class ElectricMotor:
    def cost_per_km(self): return 1.5
class DieselEngine:
    def cost_per_km(self): return 9

class Van:
    def __init__(self, reg, engine):
        self.reg, self.engine = reg, engine
    def cost(self, km):
        return self.engine.cost_per_km() * km

van = Van('KL-07-5', ElectricMotor())

Engines can be swapped without new subclasses. Composition keeps classes small and avoids deep, fragile hierarchies.

A **unit test** checks one small piece of code automatically. With Python's pytest:

# pricing.py
def final_price(mrp, pct):
    if not 0 <= pct <= 100:
        raise ValueError('pct must be 0–100')
    return round(mrp * (1 - pct / 100), 2)

# test_pricing.py
import pytest
from pricing import final_price
def test_normal():
    assert final_price(1000, 20) == 800
def test_free():
    assert final_price(1000, 100) == 0
def test_invalid():
    with pytest.raises(ValueError):
        final_price(1000, 120)

Run with: pytest. In JavaScript, Jest or Vitest look similar: expect(finalPrice(1000, 20)).toBe(800).

